def analyze(g,name):
    H,W=len(g),len(g[0])
    # find sep rows
    sepR={r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=0}
    sepC={c for c in range(W) if len({g[r][c] for r in range(H)})==1 and g[0][c]!=0}
    def tilesb(n,sep):
        b=[];prev=-1
        for x in range(n):
            if x in sep:
                if prev>=0: b.append((prev+1,x-1))
                prev=x
            else: prev=x
        if prev+1<=n-1: b.append((prev+1,n-1))
        return b
    rb=tilesb(H,sepR); cb=tilesb(W,sepC)
    print(name,'H',H,'W',W,'sepR',sorted(sepR),'sepC',sorted(sepC))
    print('row bands:',rb)
    print('col bands:',cb)
    for i,(r0,r1) in enumerate(rb):
        row=[]
        for j,(c0,c1) in enumerate(cb):
            tile=[[g[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
            nz=[(r-r0,c-c0,g[r][c]) for r,c,v in [(a,b,g[a][b]) for a in range(r0,r1+1) for b in range(c0,c1+1)] if v!=0 and g[r][c]!=g[0][0]]
