    seen=set(); comps=[]
    for a in range(H):
        for b in range(W):
            if g[a][b]!=0 and g[a][b]!=0: continue
    # use sc from row separators
    sc=None
    if sepR: sc=Counter(g[r][0] for r in sepR).most_common(1)[0][0]
    else: sc=Counter(g[0][c] for c in sepC).most_common(1)[0][0]
    seen=set(); comps=[]
    for a in range(H):
        for b in range(W):
            if g[a][b]!=0 and g[a][b]!=sc and (a,b) not in seen:
                st=[(a,b)]; comp=[]
                while st:
                    r,c=st.pop()
                    if (r,c) in seen or g[r][c]!=g[r][c]: pass
                    seen.add((r,c)); comp.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<H and 0<=nc<W and g[nr][nc]!=0 and g[nr][nc]!=sc and (nr,nc) not in seen:
                            st.append((nr,nc))
                comps.append(comp)
    boxes=[]
    for comp in comps:
        rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
        n=min(rs); m0=min(cs)
        boxes.append(((n,m0),((max(rs)-min(rs)),max(cs)-min(cs)),sorted((r-n,c-m0,g[p[0]][p[1]]) for p in comp)))
    return sc, boxes

