from collections import Counter
def extract(g):
    H,W=len(g),len(g[0])
    sepR={r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=0}
    sepC={c for c in range(W) if all(g[a][c]==g[0][c] for a in range(H)) and g[0][c]!=0}
    seen=set(); comps=[]
    sc=None
    # determine separator color as most common nonzero full-line color
    rowcols=Counter()
    for r in sepR: rowcols[g[r][0]]+=1
    if rowcols: sc=rowcols.most_common(1)[0][0]
    else:
        cc=Counter()
        for c in sepC: cc[g[0][c]]+=1
        sc=cc.most_common(1)[0][0]
    for a in range(H):
        for b in range(W):
            v=g[a][b]
            if v==0 or v==sc or (a,b) in seen: continue
            st=[(a,b)]; comp=[]
            while st:
                r,c=st.pop()
                if (r,c) in seen or not(0<=r<H and 0<=c<W): continue
                seen.add((r,c)); comp.append((r,c))
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=r+dr,c+dc
                    st.append((nr,nc))
            rs=[p[0] for p in comp]; cs=[p[1] for p in comp]
            n0,m0=min(rs),min(cs)
            comps.append(((n0,m0),(max(rs)-n0,max(cs)-m0),sorted((r-n0,c-m0,v) for r,c,_ in [(p,p,g[p[0]][p[1]]) for p in comp]) for ... ))
    return sc, comps

def cells_of(g,a0,b0,r0,c0):
    cells=[(r-a0,c-b0,g[r][c]) for r in range(a0,a0+r0+1) for c in range(b0,b0+c0+1) if g[r][c]!=0 and g[r][c]!=6]
    return sorted(cells)

